fun render(holder: SurfaceHolder) {
    val canvas = holder.lockCanvas() ?: return   // back buffer; null when not ready
    try {
        drawFrame(canvas)                        // complete frame while locked
    } finally {
        holder.unlockCanvasAndPost(canvas)       // post: the compositor flips it
    }
}
